#!/bin/bash
# A2b (D1 / MFA-1, owner 2026-10-14): brings an existing dev realm to the sign-in in realm-rehletshifaa.json.
# Generated by generate_sync_authentication.py from sign_in_spec.py (the realm files carry the same flows);
# run by the keycloak-sync service after the partial import.
# Idempotent: flows are built only when missing, everything else is (re)applied. Dev only.
set -euo pipefail
K=/opt/keycloak/bin/kcadm.sh
REALM="${REALM:-rehletshifaa}"; KC_CONFIG="${KC_CONFIG:-/tmp/kcadm.config}"
CFG=(--config "$KC_CONFIG" -r "$REALM")

flow_exists() { $K get authentication/flows "${CFG[@]}" --fields alias --format csv --noquotes | grep -qx "$1"; }
create_top() { $K create authentication/flows "${CFG[@]}" -s alias="$1" -s providerId=basic-flow -s topLevel=true -s builtIn=false -s description="$2" >/dev/null; }
add_exec() { $K create "authentication/flows/$1/executions/execution" "${CFG[@]}" -s provider="$2" -i; }
add_flow() {
  local flow_id; flow_id=$($K create "authentication/flows/$1/executions/flow" "${CFG[@]}" -s alias="$2" -s type=basic-flow -s provider=registration-page-form -s description="$3" -i)
  $K get "authentication/flows/$1/executions" "${CFG[@]}" --fields id,flowId --format csv --noquotes | grep ",$flow_id$" | cut -d, -f1
}
set_req() {
  local priority; priority=$($K get "authentication/flows/$1/executions" "${CFG[@]}" --fields id,priority --format csv --noquotes | grep "^$2," | cut -d, -f2)
  $K update "authentication/flows/$1/executions" "${CFG[@]}" -n -b "{\"id\":\"$2\",\"requirement\":\"$3\",\"priority\":$priority}"
}
add_config() { $K create "authentication/executions/$1/config" "${CFG[@]}" -b "$2" >/dev/null; }

# The staff marker the sign-in keys on.
$K get roles/rs-staff "${CFG[@]}" >/dev/null 2>&1 || $K create roles "${CFG[@]}" -s name=rs-staff -s 'description=Works on cases or the platform: signs in with a second factor (D1). Set by the platform when staff are invited.'

if ! flow_exists rehletshifaa-browser; then
  create_top rehletshifaa-browser 'Sign-in: password, then the second factor the person has (passkey, authenticator app or recovery code); staff without one enrol now'
  id=$(add_exec rehletshifaa-browser auth-cookie); set_req rehletshifaa-browser "$id" ALTERNATIVE
  id=$(add_flow rehletshifaa-browser rehletshifaa-sign-in 'Password and second factor'); set_req rehletshifaa-browser "$id" ALTERNATIVE
  id=$(add_exec rehletshifaa-sign-in auth-username-password-form); set_req rehletshifaa-sign-in "$id" REQUIRED; add_config "$id" '{"alias": "rs-amr-pwd", "config": {"default.reference.value": "pwd", "default.reference.maxAge": "36000"}}'
  id=$(add_flow rehletshifaa-sign-in rehletshifaa-second-factor 'Anyone who has a second factor uses it, at every sign-in, from every client: passkey, authenticator app or a recovery code'); set_req rehletshifaa-sign-in "$id" CONDITIONAL
  id=$(add_exec rehletshifaa-second-factor conditional-user-configured); set_req rehletshifaa-second-factor "$id" REQUIRED
  id=$(add_exec rehletshifaa-second-factor webauthn-authenticator); set_req rehletshifaa-second-factor "$id" ALTERNATIVE; add_config "$id" '{"alias": "rs-amr-hwk", "config": {"default.reference.value": "hwk", "default.reference.maxAge": "36000"}}'
  id=$(add_exec rehletshifaa-second-factor auth-otp-form); set_req rehletshifaa-second-factor "$id" ALTERNATIVE; add_config "$id" '{"alias": "rs-amr-otp", "config": {"default.reference.value": "otp", "default.reference.maxAge": "36000"}}'
  id=$(add_exec rehletshifaa-second-factor auth-recovery-authn-code-form); set_req rehletshifaa-second-factor "$id" ALTERNATIVE; add_config "$id" '{"alias": "rs-amr-recovery", "config": {"default.reference.value": "mfa", "default.reference.maxAge": "36000"}}'
  id=$(add_flow rehletshifaa-sign-in rehletshifaa-staff-enrolment 'Staff without a second factor set one up at this sign-in'); set_req rehletshifaa-sign-in "$id" CONDITIONAL
  id=$(add_exec rehletshifaa-staff-enrolment conditional-user-role); set_req rehletshifaa-staff-enrolment "$id" REQUIRED; add_config "$id" '{"alias": "rs-cond-staff", "config": {"condUserRole": "rs-staff", "negate": "false"}}'
  id=$(add_exec rehletshifaa-staff-enrolment conditional-sub-flow-executed); set_req rehletshifaa-staff-enrolment "$id" REQUIRED; add_config "$id" '{"alias": "rs-cond-no-second-factor", "config": {"flow_to_check": "rehletshifaa-second-factor", "check_result": "not-executed"}}'
  id=$(add_exec rehletshifaa-staff-enrolment auth-otp-form); set_req rehletshifaa-staff-enrolment "$id" REQUIRED; add_config "$id" '{"alias": "rs-amr-otp-enrol", "config": {"default.reference.value": "otp", "default.reference.maxAge": "36000"}}'
  create_top rehletshifaa-direct-grant-denied 'No password-only tokens: every token comes from the browser sign-in'
  id=$(add_exec rehletshifaa-direct-grant-denied deny-access-authenticator); set_req rehletshifaa-direct-grant-denied "$id" REQUIRED; add_config "$id" '{"alias": "rs-deny-direct-grant", "config": {"denyErrorMessage": "Sign in through the RehletShifaa website."}}'
  create_top rehletshifaa-reset-credentials 'Password reset proves the second factor before the new password'
  id=$(add_exec rehletshifaa-reset-credentials reset-credentials-choose-user); set_req rehletshifaa-reset-credentials "$id" REQUIRED
  id=$(add_exec rehletshifaa-reset-credentials reset-credential-email); set_req rehletshifaa-reset-credentials "$id" REQUIRED
  id=$(add_flow rehletshifaa-reset-credentials rehletshifaa-reset-second-factor 'A reset never bypasses a second factor the person has'); set_req rehletshifaa-reset-credentials "$id" CONDITIONAL
  id=$(add_exec rehletshifaa-reset-second-factor conditional-user-configured); set_req rehletshifaa-reset-second-factor "$id" REQUIRED
  id=$(add_exec rehletshifaa-reset-second-factor webauthn-authenticator); set_req rehletshifaa-reset-second-factor "$id" ALTERNATIVE
  id=$(add_exec rehletshifaa-reset-second-factor auth-otp-form); set_req rehletshifaa-reset-second-factor "$id" ALTERNATIVE
  id=$(add_exec rehletshifaa-reset-second-factor auth-recovery-authn-code-form); set_req rehletshifaa-reset-second-factor "$id" ALTERNATIVE
  id=$(add_exec rehletshifaa-reset-credentials reset-password); set_req rehletshifaa-reset-credentials "$id" REQUIRED
  echo "keycloak-sync: sign-in flows built"
fi

$K update "realms/$REALM" --config "$KC_CONFIG" -s browserFlow=rehletshifaa-browser -s directGrantFlow=rehletshifaa-direct-grant-denied \
  -s resetCredentialsFlow=rehletshifaa-reset-credentials -s bruteForceProtected=true -s permanentLockout=false -s maxFailureWaitSeconds=900 -s minimumQuickLoginWaitSeconds=60 -s waitIncrementSeconds=60 -s quickLoginCheckMilliSeconds=1000 -s maxDeltaTimeSeconds=43200 -s failureFactor=5
flow_exists rehletshifaa-browser-step-up && $K delete "authentication/flows/$($K get authentication/flows "${CFG[@]}" --fields id,alias --format csv --noquotes | grep ",rehletshifaa-browser-step-up$" | cut -d, -f1)" "${CFG[@]}" && echo "keycloak-sync: old step-up flows removed"

# No password-only tokens from Keycloak's own command-line client either.
cli=$($K get clients "${CFG[@]}" -q clientId=admin-cli --fields id --format csv --noquotes)
$K update "clients/$cli" "${CFG[@]}" -s directAccessGrantsEnabled=false

# Tokens say how the person signed in (amr), which the backend checks.
web=$($K get clients "${CFG[@]}" -q clientId=rehletshifaa-web --fields id --format csv --noquotes)
$K get "clients/$web/protocol-mappers/models" "${CFG[@]}" --fields name --format csv --noquotes | grep -qx amr || \
  $K create "clients/$web/protocol-mappers/models" "${CFG[@]}" -b '{"name": "amr", "protocol": "openid-connect", "protocolMapper": "oidc-amr-mapper", "consentRequired": false, "config": {"id.token.claim": "true", "access.token.claim": "true", "introspection.token.claim": "true", "userinfo.token.claim": "false"}}'

$K update events/config "${CFG[@]}" -b '{"eventsEnabled": true, "eventsExpiration": 7776000, "enabledEventTypes": ["LOGIN_ERROR", "UPDATE_CREDENTIAL", "REMOVE_CREDENTIAL", "UPDATE_TOTP", "REMOVE_TOTP", "UPDATE_PASSWORD", "RESET_PASSWORD", "RESET_PASSWORD_ERROR", "CUSTOM_REQUIRED_ACTION", "EXECUTE_ACTIONS", "SEND_RESET_PASSWORD", "CODE_TO_TOKEN_ERROR", "USER_DISABLED_BY_TEMPORARY_LOCKOUT", "USER_DISABLED_BY_PERMANENT_LOCKOUT"], "adminEventsEnabled": true, "adminEventsDetailsEnabled": false, "eventsListeners": ["jboss-logging"]}'

for user in coordinator coordinator2 doctor doctor-orthopedics operations finance credential-admin journey-manager journey-approver compliance-auditor support-officer patient-identity-reviewer operations-manager finance-manager credentialing-manager support-manager care-manager consultant-operations-manager coordinator-scope care-manager-scope; do
  $K add-roles "${CFG[@]}" --uusername "$user" --rolename rs-staff 2>/dev/null || true
done
# Imported users get only the roles listed, so seeded people need the default role (account console: authenticator app,
# passkeys, password) granted here too.
for user in patient coordinator coordinator2 doctor doctor-orthopedics operations finance credential-admin journey-manager journey-approver compliance-auditor support-officer patient-identity-reviewer operations-manager finance-manager credentialing-manager support-manager care-manager consultant-operations-manager coordinator-scope care-manager-scope; do
  $K add-roles "${CFG[@]}" --uusername "$user" --rolename "default-roles-$REALM" 2>/dev/null || true
done
echo "keycloak-sync: second factor enforced by Keycloak for staff and for anyone who has one"
